const platformColors = {
  Steam: '#d23f31',
  Playstation: '#3358d4',
  Xbox: '#2f9d58'
};

const IGNORED_CHILDLIKE_TITLES = new Set([
  'minecraft',
  'minecraft dungeons',
  'roblox',
  'jurassic world evolution',
  'jurassic world evolution 2',
  'jurassic world evolution 3',
  'teardown',
  'microsoft solitaire collection',
  'microsoft wordament'
]);

const columns = [
  { key: 'platform', label: 'Plataforma' },
  { key: 'title', label: 'Jogo' },
  { key: 'achievements', label: 'Conquistas' },
  { key: 'percent', label: '%', numeric: true, render: row => row.percent == null ? '-' : row.percent.toFixed(2) + '%' },
  { key: 'minutes', label: 'Tempo', numeric: true, render: row => formatMinutes(row.minutes) },
  { key: 'started', label: 'Iniciado', render: row => formatDateish(row.started) },
  { key: 'completed', label: 'Completo', render: row => formatDateish(row.completed) },
  { key: 'lastWin', label: 'Ultima conquista', render: row => formatDateish(row.lastWin) },
  { key: 'ownership', label: 'Posse' }
];

let state = { sortKey: 'minutes', sortDirection: 'desc', search: '', platform: '' };

document.addEventListener('DOMContentLoaded', () => {
  renderSummary();
  renderLegend();
  renderChart();
  wireChartTabs();
  renderPlatformFilter();
  renderTableHeader();
  renderTable();

  document.getElementById('searchBox').addEventListener('input', event => {
    state.search = normalize(event.target.value);
    renderTable();
  });

  document.getElementById('platformFilter').addEventListener('change', event => {
    state.platform = event.target.value;
    renderTable();
  });
});

function renderSummary() {
  const totalMinutes = GAME_STATS_DATA.reduce((sum, row) => sum + row.minutes, 0);
  const completed = GAME_STATS_DATA.filter(row => row.percent === 100).length;
  const achievements = GAME_STATS_DATA.reduce((sum, row) => sum + (row.unlocked || 0), 0);
  const platforms = new Set(GAME_STATS_DATA.map(row => row.platform)).size;
  const cards = [
    ['Jogos', GAME_STATS_DATA.length.toLocaleString('pt-BR'), platforms + ' plataformas'],
    ['Tempo total', formatMinutes(totalMinutes), (totalMinutes / 60).toLocaleString('pt-BR', { maximumFractionDigits: 0 }) + ' horas'],
    ['100%', completed.toLocaleString('pt-BR'), 'com todas as conquistas'],
    ['Conquistas', achievements.toLocaleString('pt-BR'), 'linhas com fracao']
  ];

  document.querySelector('.summary-grid').innerHTML = cards.map(([label, value, note]) => `
    <article class="summary-card">
      <div class="label">${escapeHtml(label)}</div>
      <div class="value">${escapeHtml(value)}</div>
      <div class="note">${escapeHtml(note)}</div>
    </article>
  `).join('');
}

function renderLegend() {
  const platforms = [...new Set(GAME_STATS_DATA.map(row => row.platform))].sort();
  document.querySelector('.legend').innerHTML = platforms.map(platform => `
    <span class="legend-item"><span class="legend-swatch" style="background:${platformColor(platform)}"></span>${escapeHtml(platform)}</span>
  `).join('');
}

function renderChart() {
  renderChartInto('topChart', false);
  renderChartInto('topChartWithoutKids', true);
}

function renderChartInto(elementId, withoutChildlikeGames) {
  const top = [...groupByGame().values()]
    .filter(item => !withoutChildlikeGames || !IGNORED_CHILDLIKE_TITLES.has(normalizeTitle(item.title)))
    .sort((a, b) => b.totalMinutes - a.totalMinutes)
    .slice(0, 20);
  const max = Math.max(...top.map(item => item.totalMinutes), 1);

  document.getElementById(elementId).innerHTML = top.map(item => {
    const segments = Object.entries(item.platforms).sort(([a], [b]) => a.localeCompare(b)).map(([platform, minutes]) => {
      const width = Math.max((minutes / item.totalMinutes) * 100, 1.5);
      const title = `${platform}: ${formatMinutes(minutes)}`;
      return `<span class="segment" title="${escapeHtml(title)}" style="width:${width}%; background:${platformColor(platform)}"></span>`;
    }).join('');
    const barWidth = Math.max((item.totalMinutes / max) * 100, 3);
    return `
      <div class="chart-row">
        <div class="chart-title" title="${escapeHtml(item.title)}">${escapeHtml(item.title)}</div>
        <div class="bar-track"><div class="bar" style="width:${barWidth}%">${segments}</div></div>
        <div class="chart-total">${formatMinutes(item.totalMinutes)}</div>
      </div>
    `;
  }).join('');
}

function wireChartTabs() {
  document.querySelectorAll('.chart-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const target = tab.dataset.chart;
      document.querySelectorAll('.chart-tab').forEach(item => {
        const active = item === tab;
        item.classList.toggle('active', active);
        item.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      document.querySelectorAll('.chart').forEach(chart => {
        const active = chart.id === target;
        chart.classList.toggle('active', active);
        chart.hidden = !active;
      });
    });
  });
}

function renderPlatformFilter() {
  const select = document.getElementById('platformFilter');
  const platforms = [...new Set(GAME_STATS_DATA.map(row => row.platform))].sort();
  select.innerHTML = '<option value="">Todas as plataformas</option>' + platforms.map(platform => `<option value="${escapeHtml(platform)}">${escapeHtml(platform)}</option>`).join('');
}

function renderTableHeader() {
  document.querySelector('#statsTable thead').innerHTML = '<tr>' + columns.map(column => {
    const sorted = state.sortKey === column.key ? (state.sortDirection === 'asc' ? ' ▲' : ' ▼') : '';
    return `<th data-key="${column.key}" class="${column.numeric ? 'numeric' : ''}">${escapeHtml(column.label + sorted)}</th>`;
  }).join('') + '</tr>';

  document.querySelectorAll('#statsTable th').forEach(th => {
    th.addEventListener('click', () => {
      const key = th.dataset.key;
      if (state.sortKey === key) {
        state.sortDirection = state.sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        state.sortKey = key;
        state.sortDirection = columns.find(column => column.key === key)?.numeric ? 'desc' : 'asc';
      }
      renderTableHeader();
      renderTable();
    });
  });
}

function renderTable() {
  const tbody = document.querySelector('#statsTable tbody');
  const rows = filteredRows().sort(compareRows);

  if (rows.length === 0) {
    tbody.innerHTML = `<tr><td class="empty" colspan="${columns.length}">Nenhum jogo encontrado.</td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(row => '<tr>' + columns.map(column => {
    const value = column.render ? column.render(row) : (row[column.key] || '-');
    if (column.key === 'platform') {
      return `<td><span class="platform-pill" style="background:${platformColor(row.platform)}">${escapeHtml(value)}</span></td>`;
    }
    return `<td class="${column.numeric ? 'numeric' : ''}">${escapeHtml(value)}</td>`;
  }).join('') + '</tr>').join('');
}

function filteredRows() {
  return GAME_STATS_DATA.filter(row => {
    const platformMatches = !state.platform || row.platform === state.platform;
    const haystack = normalize([row.platform, row.title, row.achievements, row.timePlayed, row.ownership].join(' '));
    return platformMatches && (!state.search || haystack.includes(state.search));
  });
}

function compareRows(a, b) {
  const column = columns.find(item => item.key === state.sortKey);
  let av = a[state.sortKey];
  let bv = b[state.sortKey];

  if (column?.numeric) {
    av = av == null ? -Infinity : Number(av);
    bv = bv == null ? -Infinity : Number(bv);
  } else {
    av = normalize(av || '');
    bv = normalize(bv || '');
  }

  if (av < bv) return state.sortDirection === 'asc' ? -1 : 1;
  if (av > bv) return state.sortDirection === 'asc' ? 1 : -1;
  return normalize(a.title).localeCompare(normalize(b.title));
}

function groupByGame() {
  const grouped = new Map();
  GAME_STATS_DATA.forEach(row => {
    const key = normalizeTitle(row.title);
    if (!grouped.has(key)) grouped.set(key, { title: row.title, totalMinutes: 0, platforms: {} });
    const item = grouped.get(key);
    item.totalMinutes += row.minutes;
    item.platforms[row.platform] = (item.platforms[row.platform] || 0) + row.minutes;
  });
  return grouped;
}

function normalizeTitle(value) {
  return normalize(value)
    .replace(/\s*\((ps[345]|ps3\s*\/\s*vita|playstation|xbox[^)]*|steam|pc|uwp|mobile)\)\s*$/i, '')
    .replace(/[™®©]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function normalize(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function formatMinutes(minutes) {
  const total = Number(minutes) || 0;
  const hrs = Math.floor(total / 60);
  const mins = total % 60;
  if (hrs === 0) return `${mins} min`;
  if (mins === 0) return `${hrs} h`;
  return `${hrs} h ${mins} min`;
}

function formatDateish(value) {
  if (!value) return '-';
  if (/^\d+$/.test(String(value))) {
    const serial = Number(value);
    const date = new Date(Date.UTC(1899, 11, 30 + serial));
    return date.toLocaleDateString('pt-BR');
  }
  return value;
}

function platformColor(platform) {
  return platformColors[platform] || '#7b8794';
}

function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}












